125	// then run the resolved engine standalone with `extra` (model flags the
126	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
127	// `clean_output` picks how the engine's output is presented: fast inherits the
128	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
129	// semihosting console works unchanged); cycle filters out the engine's banner +
130	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
131	// exit code propagates. The per-model engine + selection are resolved by the
132	// caller; `model` here only labels the positional diagnostics.
133	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
134	                   const char* model, const std::vector<std::string>& extra = {},
135	                   bool clean_output = false) {
136	  if (int rc = check_one_elf(cli, model)) return rc;
137	  // QEMU's -bios flag searches its data directory for relative paths rather
138	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
139	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
140	  if (elf.empty()) return 2;
141	  std::vector<std::string> args = extra;
142	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
143	  std::string err;
144	  const std::vector<std::string> argv =
145	      passthrough_argv(eng, "standalone", elf, args, err);
146	  if (!err.empty()) {
147	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
148	    return 2;
149	  }
150	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
151	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
152	  if (cli.dry_run)
153	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
154	  // Trace mirrors the hybrid legs' exec lines: emitted BEFORE the spawn, so a
155	  // wedged engine still leaves the exact command in the log.
156	  log_line(kLogTrace, "[andesim] exec standalone [%s]: %s", eng.id.c_str(),
157	           render_argv(argv).c_str());
158	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
159	}
