#include "engine_registry.hpp"

#include <algorithm>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>

#include <unistd.h>

#include "config_env.hpp"
#include "json.hpp"
#include "process.hpp"
#include "repo_root.hpp"

namespace fs = std::filesystem;

namespace andes_sim {

// The bundled functional engine(s). QEMU does not implement --describe, so the
// descriptor is built in. builtin_qemu_arch(64) is the rv64 "qemu64";
// builtin_qemu_arch(32) is the rv32 "qemu32" (qemu-system-riscv32). The
// standalone (model=fast) run uses qemu's OWN default -cpu -- the user's post-`--`
// args (incl. an explicit -cpu) still win; only the rv64 hybrid fast-leg pins a
// -cpu. Binary path honors $VSIM_QEMU / $VSIM_QEMU32, then $QEMU_BIN_DIR (env or
// config.env), then the legacy in-tree build. Exposed (engine_registry.hpp) so
// `run --mode fast` resolves qemu directly, skipping the per-engine --describe
// scan whole-registry discovery would spawn.
EngineDescriptor builtin_qemu_arch(int xlen) {
  const bool rv32 = (xlen == 32);
  EngineDescriptor d;
  d.id = rv32 ? kQemuId32 : kQemuId64;
  d.type = "qemu";
  d.kind = "functional";
  d.xlen = xlen;
  d.triggers = {"marker", "pc"};
  d.state = {"drain"};
  d.source = "built-in";

  d.roles = {"standalone"};
  if (!rv32) {  // hybrid rv32 (qemu32 fast-leg + engine-matched -cpu) not wired yet
    // The hybrid fast-forward leg (rv64): load the ELF, drain on the plugin's
    // trigger into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out}
    // are filled by the plan executor (F6); {trigger} is the plugin comma-suffix
    // (empty for marker), folded by leg_trigger_args (F9).
    d.roles.push_back("fast-leg");
    // {qemu_cpu}: the accurate engine's CPU model (from its --print-qemu-config
    // driver globals; run_plan falls back to the andes-ax45mpv family default).
    // The -readconfig globals apply only to the driver they name, so the model
    // must follow the engine -- andes-ax45mpv silently kept vlen=512 when the
    // ax66 (VLEN 128) pairing asked for 128.
    d.invoke.push_back(
        {"fast-leg",
         {"{bin}", "-object",
          "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
          "-machine", "andes_ae350,memory-backend=mem", "-cpu",
          "{qemu_cpu},vlen={vlen}", "-nographic", "-semihosting-config",
          "enable=on,target=native", "-bios", "{elf}", "-plugin",
          "{plugin},outfile={state_out}{trigger}"}});
  }

  // The standalone functional run (model=fast). andes_ae350's generic default
  // -cpu hangs the vplat fixtures, so pin a concrete andes core: the
  // vector-capable andes-ax46mpv (rv64) / andes-a46mpv (rv32). We pass NO vlen --
  // the cpu model's own QEMU default applies, so both scalar and vector binaries
  // run out of the box; a user who needs a specific width passes it via the
  // post-`--` -cpu (e.g. -cpu andes-ax46mpv,vlen=512), which still wins.
  // run_passthrough fills {bin}/{elf}.
  const char* fast_cpu = rv32 ? "andes-a46mpv" : "andes-ax46mpv";
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", fast_cpu, "-nographic",
        "-semihosting-config", "enable=on,target=native", "-bios", "{elf}"}});

  const std::string sys =
      std::string("qemu-system-") + (rv32 ? "riscv32" : "riscv64");
  const char* env = rv32 ? "VSIM_QEMU32" : "VSIM_QEMU";
  if (const char* q = std::getenv(env); q && *q)
    d.bin_path = q;
  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
    d.bin_path = (fs::path(qd) / sys).string();
  else
    d.bin_path = (repo_root() / "build" / "qemu" / sys).string();
  return d;
}

// rv64 qemu (back-compat: the default functional engine and hybrid fast leg).
EngineDescriptor builtin_qemu() { return builtin_qemu_arch(64); }

namespace {

constexpr int kDescribeTimeoutMs = 5000;

bool is_executable_file(const fs::path& p) {
  std::error_code ec;
  if (!fs::is_regular_file(p, ec)) return false;
  return ::access(p.c_str(), X_OK) == 0;
}

// The hybrid guest memory map: which regions a workload may touch in
// `run --mode hybrid`, composed from the same sources the run itself trusts.
//
// Only hybrid-SUPPORTED regions appear (PM rule): regions modeled by BOTH
// engines whose content or device behavior the handoff actually provides.
// QEMU-only devices (MROM/PLIC/PLMT/virtio/...), vsim-reserved holes (PLDM),
// and unverified-parity devices (UART1/SMU) are deliberately absent.
//
// Sources, in provenance order:
//   - DRAM + V-scratch: the driver's own window math (--mem-size; the
//     reserved HYBRID_V_SCRATCH_BYTES page above program RAM, L26).
//   - ILM/DLM/HVM bases: the engine's `--print-qemu-config` text -- the same
//     staged qemu.cfg the QEMU fast leg boots with, so the printed bases are
//     exactly the run's effective geometry.
//   - ILM/DLM/HVM sizes + row presence: the engine descriptor's backdoor-gated
//     ilm/dlm/hvm_size (0 = content cannot cross the handoff -> row omitted).
//   - SimControl/HTIF + UART2: fixed AE350 platform constants, identical in
//     QEMU (hw/riscv/andes_ae350.c memmap table) and vsim (platform
//     memory_map.h); drift is guarded by tests/andes_sim/
//     test_andes_sim_print_memmap.sh, which cross-checks the engine's own
//     `--print-memmap` dump.
//   - L2C register window (0xe0500000): intentionally absent until an engine
//     ships with an L2C -- `--describe` carries no L2C capability today, and
//     every current engine is built _NDS_L2C_CACHE_SIZE_KB=0.
#ifndef ANDESIM_MEMMAP_HPP
#define ANDESIM_MEMMAP_HPP

#include <cstdint>
#include <map>
#include <string>
#include <vector>

#include "engine_descriptor.hpp"

namespace andes_sim {

struct MemmapRow {
  std::string region;     // "DRAM", "V-scratch", "ILM", ...
  uint64_t base = 0;      // guest physical, first byte
  uint64_t end = 0;       // guest physical, LAST byte (inclusive)
  std::string transport;  // what the handoff does with the region's content
};

struct MemmapResult {
  std::vector<MemmapRow> rows;
  std::vector<std::string> warnings;  // e.g. LM geometry unavailable
};

// Extract the `riscv.andes.ae350.soc` [global] properties from an engine's
// --print-qemu-config text: property name -> value string, other drivers'
// globals (the CPU ISA block) excluded.
std::map<std::string, std::string> qemu_cfg_soc_props(
    const std::string& cfg_text);

// Compose the hybrid map for `eng` with `mem_size` bytes of program RAM
// (--mem-size) and the engine's --print-qemu-config text (may be empty:
// LM/HVM rows are then dropped with a warning naming the missing probe).
MemmapResult hybrid_memmap(const EngineDescriptor& eng, long long mem_size,
                           const std::string& qemu_cfg_text);

// "128M" / "4K" / "2G" for whole binary multiples, plain decimal bytes else.
std::string fmt_size(uint64_t bytes);

// Render as an aligned text table (REGION/BASE/END/SIZE/TRANSPORT), warnings
// appended one per line.
std::string render_memmap(const MemmapResult& r);

}  // namespace andes_sim

#endif  // ANDESIM_MEMMAP_HPP

/* Unified linker script for all hybrid test fixtures.
 *
 * Load base: 0x00100000 (1 MiB into andes_ae350 DRAM).
 *
 * andes_ae350 memory map:
 *   DRAM : 0x00000000 .. 0x7FFFFFFF  (writable, executable)
 *   MROM : 0x80000000 .. 0x87FFFFFF  (read-only)
 *
 * Reserved scratch (below text, used by .S fixtures):
 *   0x00000004              rt_csr_survival mtvec test value
 *   0x00001000              semihost_exit.inc param block
 *   0x00002000              rt_all_gprs spill area
 *   0x00003000              rt_mem_loadstore / rt_unaligned_lh buffer
 *   0x00010000              rt_shared_mem 4 KB buffer
 *
 * Layout above 0x00100000:
 *   .text         pinned at 0x00100000 (entry _start)
 *   .rodata
 *   .preinit_array/.init_array/.fini_array + EH tables (C++ runtime;
 *                 deliberately ABOVE _edata, see the comment there)
 *   .data         _edata terminates .data
 *   .bss          _end   terminates .bss (crt0 zeros [.bss, _end))
 *   _stack        0x00700000 (used by crt0.S to init sp)
 *
 * V-register transport scratch (L26): NOT a fixed address any more. The driver
 * maps one 4 KiB page above --mem-size and parks the scratch there (the mmap's
 * top page, v_scratch_gpa = ram_base + --mem-size), so it sits just past the
 * program's RAM -- nothing in this script can collide with it. No reservation
 * needed here.
 *
 * .S fixtures with no .data/.bss leave those sections empty (zero cost).
 * C fixtures rely on _edata / _end / _stack.
 */

ENTRY(_start)

SECTIONS {
    . = 0x00100000;

    .text : {
        *(.text.init)
        *(.text*)
    }

    .rodata : {
        *(.rodata*)
        *(.srodata*)
    }

    /* C++ constructor/destructor arrays and EH metadata. Everything here
     * must stay ABOVE _edata: crt0 zeroes [_edata, _end) before it walks
     * .init_array, so an array placed after .data would be wiped first.
     * crt0.S runs newlib's __libc_init_array, which reads the WEAK
     * start/end symbols below -- without these PROVIDEs they resolve to
     * 0 and no constructor ever runs. KEEP: entries are only referenced
     * through these bounds, never by symbol. */
    .preinit_array : {
        PROVIDE_HIDDEN(__preinit_array_start = .);
        KEEP(*(.preinit_array))
        PROVIDE_HIDDEN(__preinit_array_end = .);
    }
    .init_array : {
        PROVIDE_HIDDEN(__init_array_start = .);
        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*) SORT_BY_INIT_PRIORITY(.ctors.*)))
        KEEP(*(.init_array .ctors))
        PROVIDE_HIDDEN(__init_array_end = .);
    }
    .fini_array : {
        PROVIDE_HIDDEN(__fini_array_start = .);
        KEEP(*(SORT_BY_INIT_PRIORITY(.fini_array.*) SORT_BY_INIT_PRIORITY(.dtors.*)))
        KEEP(*(.fini_array .dtors))
        PROVIDE_HIDDEN(__fini_array_end = .);
    }
    /* crtbegin.o's __EH_FRAME_BEGIN__ leads and crtend.o's terminator
     * closes .eh_frame via the specs' startfile/endfile link order. */
    .eh_frame : { KEEP(*(.eh_frame)) }
    .gcc_except_table : { *(.gcc_except_table*) }

    .data : {
        *(.data*)
        *(.sdata*)
    }
    _edata = .;

    .bss : {
        *(.bss*)
        *(.sbss*)
        *(COMMON)
    }
    _end = .;

    /* Default stack top; the V-transport scratch lives above program RAM
     * (top of the shared mmap), so no headroom below it is needed here.
     * Override at link time with -Wl,--defsym,_stack=... if needed. */
    PROVIDE(_stack = 0x00700000);
}

